             // NOT FOUND
             return;
      }
      std::string systemName = found.second.begin()->first;
```

What if making this as a function?
```
sdbusplus::message::object_path getHostStateObjectPath(
        const uint64_t computerSystemIndex)
{
    return sdbusplus::message::object_path("/xyz/openbmc_project/state/host" 
            + std::to_string(computerSystemIndex));
}
```

I think it may be better to make L540-L545-L856 as a function like
```
std::string getHostStateServiceName(const uint64_t computerSystemIndex)
{
    std::string service = "xyz.openbmc_project.State.Host";

    if (BMCWEB_EXPERIMENTAL_REDFISH_MULTI_COMPUTER_SYSTEM)
    {
        service.append(std::to_string(computerSystemIndex));
    }
    return service;
}
```

